  "objects": [
    {
      "objectType": "Concept",
      "evidenceQuote": "**执行工具**是 Agent 改变外部世界的方式。例如，命令行工具（shell_exec）、代码解释器工具（code_interpreter）、写文件工具（write_file）、编辑文件工具（edit_file）、发送邮件工具（send_email）。",
      "canonicalTerm": "执行工具",
      "aliases": [],
      "definition": "Agent 主动调用、用于改变外部世界的工具类型，典型实例如命令行、代码解释器、写文件、编辑文件和发送邮件工具。",
      "examples": [
        "命令行工具（shell_exec）",
        "代码解释器工具（code_interpreter）",
        "写文件工具（write_file）",
        "编辑文件工具（edit_file）",
        "发送邮件工具（send_email）"
      ]
    },
    {
      "objectType": "Concept",
      "evidenceQuote": "**事件触发工具**是外部世界驱动 Agent 行动的方式。例如，设置定时器（set_timer）、监控后台命令行任务（monitor_shell）、连接外部事件源（connect_channel）。",
      "canonicalTerm": "事件触发工具",
      "aliases": [],
      "definition": "由外部事件异步触发、唤醒 Agent 开始处理的工具类型，包含注册和触发两个时刻。",
      "examples": [
        "设置定时器（set_timer）",
        "监控后台命令行任务（monitor_shell）",
        "连接外部事件源（connect_channel）"
      ]
    }
  ]
}

{"objects": [
  {
    "objectType": "Heuristic",
    "evidenceQuote": "**默认取向：通用工具优于专用工具，除非存在明确的安全、权限或性能理由。**",
    "trigger": "在表达 Agent 能力、选择专用工具还是通用工具/Skill 时",
    "recommendation": "默认优先选择通用工具（如 code_interpreter），而非专用工具；只有在存在明确的安全、权限或性能理由时才退回专用工具。",
    "confidence": 0.8,
    "exceptions": ["存在明确的安全、权限或性能理由"]
  },
  {
    "objectType": "AntiPattern",
    "evidenceQuote": "以文档处理为例，`extract_pdf_text`、`extract_docx_content`、`extract_pptx_content` 等多个工具的共性在于：都是从文档中提取文本，输入是文件路径，输出是文本字符串。",
    "pattern": "为功能相似、使用场景重叠的能力分别提供粒度极细的专用工具，例如按 PDF、DOCX、PPTX 各建一个文本提取工具。",
    "harm": "工具数量激增，增加 LLM 的选择负担，描述不够清晰，且不易扩展以支持新格式。",
    "corrective": "提供统一的 `read_document` 工具，通过 `file_type` 参数区分格式；整合的核心标准是功能相似性和使用场景重叠度。",
    "evidence": "`extract_pdf_text`、`extract_docx_content`、`extract_pptx_content` 的输入都是文件路径、输出都是文本字符串，因而可合并为 `read_document`。"
  }
]}

{"objects": [
  {
    "objectType": "EngineeringRule",
    "evidenceQuote": "参数描述应该用具体例子代替抽象规范。“`timestamp`：RFC3339 格式，例如`2024-03-15T14:30:00Z`”比单写“RFC3339 格式”有效得多。",
    "statement": "参数描述应该用具体例子代替抽象规范。",
    "rationale": "LLM 在处理复杂任务时只能分出一小部分注意力来确认参数格式，具体例子让 Agent 可以直接套用，无需额外的思考步骤。",
    "appliesWhen": "描述工具参数格式时，尤其是需要同时处理多个工具、历史轨迹和多个决策的复杂任务场景。",
    "violation": "只写抽象规范而不提供具体例子，例如仅写“RFC3339 格式”或“E.164 格式”。"
  },
  {
    "objectType": "Heuristic",
    "evidenceQuote": "加入示例后，工具调用的准确率往往明显提升——在一些基准上可从约 72% 提升到 90%（具体数值因任务而异）。",
    "trigger": "为工具编写描述文档，并希望提升工具调用准确率时。",
    "recommendation": "为每个工具附带 1-5 个真实的调用示例，以传达参数格式和典型参数组合等隐式约定。",
    "confidence": 0.8,
    "exceptions": ["具体数值因任务而异，提升幅度不一定相同。"]
  }
]}

{"objects": [
  {
    "objectType": "AntiPattern",
    "evidenceQuote": "一种比功能缺失更隐蔽的反模式是**静默输入转换**——工具在执行前悄悄地“修正”模型的输入参数，导致实际操作偏离了模型的意图。",
    "pattern": "工具在执行前静默“修正”模型的输入参数，或静默向命令注入额外参数，导致实际操作偏离模型意图。",
    "harm": "模型反复尝试、反复失败，无法理解为什么工具找不到自己明明看到的内容；写入内容被篡改，模型陷入困惑。",
    "corrective": "工具参数传递必须保持透明，不得在模型不知情的情况下修改输入或输出；若需规范化处理，必须在工具描述中说明并在返回中明确告知模型。",
    "evidence": "Cursor 参数传递层将中文弯引号静默转换为英文直引号，导致替换失败；某 IDE bash 工具自动附加额外参数导致 git commit 报错。"
  },
  {
    "objectType": "EngineeringRule",
    "evidenceQuote": "这些问题揭示了一条更为基础的工具设计原则：**模型感知到的世界与工具操作的世界之间，不能存在系统性的偏差**。工具的参数传递必须保持透明，不得在模型不知情的情况下修改输入或输出。",
    "statement": "模型感知到的世界与工具操作的世界之间不能存在系统性偏差；工具的参数传递必须保持透明，不得在模型不知情的情况下修改输入或输出。",
    "rationale": "静默输入转换或静默参数注入会制造模型无法自行诊断的系统性故障，使模型反复失败并陷入困惑。",
    "appliesWhen": "当工具接收、写入或执行模型意图所对应的参数与命令时。",
    "violation": "参数传递层静默将中文弯引号转换为英文直引号；bash 工具在 git commit 命令中静默注入额外参数。"
  }
]}

